import { ReactNode, FC } from 'react';

type TagVariant = 'filled' | 'outline' | 'light';
type TagSize = 'sm' | 'md' | 'lg';
type TagColor = 'primary' | 'success' | 'warning' | 'error' | 'default';
interface TagProps {
    /** 变体 */
    variant?: TagVariant;
    /** 尺寸 */
    size?: TagSize;
    /** 颜色主题 */
    color?: TagColor;
    /** 自定义颜色 */
    customColor?: string;
    /** 是否圆角 */
    round?: boolean;
    /** 是否可关闭 */
    closable?: boolean;
    /** 关闭回调 */
    onClose?: () => void;
    /** 点击回调 */
    onClick?: () => void;
    /** 子元素 */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}

declare const Tag: FC<TagProps>;

export { Tag, Tag as default };
export type { TagColor, TagProps, TagSize, TagVariant };
